#!/bin/bash
# run_all_reprocessed.sh
#
# Re-run the full P2 QA pipeline over every run key that sits on the
# August-2026 reprocessed data, with the MINIMAL cut profile
# (P2_MINIMAL_CUTS=1 -- see CUTS.md, generated by dump_cuts.py).
#
# Excluded on purpose: det1_long2, det4_long1(+_stable), det2_fe55scan1,
# det3_fe55scan1 -- their raw is gone or was never on rays, so they still
# carry the pre-August reconstruction and are not comparable. Also excluded:
# det1_long5_pre/_post, whose whole purpose is a time window.
#
#   ./run_all_reprocessed.sh [-n] [-o OUTDIR] [key ...]
#     -n   dry run: print what would be run
#     -o   log directory (default: ANALYSIS_ROOT/_pipeline_logs)
#     key  restrict to these run keys
#
# Each key gets its own log; a failure is recorded and the batch continues, so
# one bad run cannot abort the rest. Summary table at the end + summary.tsv.

set -u
# Adopted profile (2026-08-12), see CUTS.md:
#   minimal cuts, EXCEPT the automatic hot-pad drop -- a handful of oscillating
#   pads carried 69% of det1_long5's hits and pinned the charge-weighted
#   centroid, dragging corr(x) to 0.65 and the efficiency to 24.6%.
#   ratio 3.0 rather than the shipped 5.0: pads at 4.3-4.9x median survived the
#   5x cut and set the linear colour scale of the surface maps.
export P2_MINIMAL_CUTS=1
export P2_MINIMAL_EXCEPT=HOT_PAD_RATIO
export P2_HOT_PAD_RATIO=3.0

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
cd "${SCRIPT_DIR}"

ANALYSIS_ROOT=$(python3 -c 'import p2_qa_config as C; print(C.ANALYSIS_ROOT)')
LOGDIR="${ANALYSIS_ROOT}/_pipeline_logs"
DRY=0
ONLY=()

while [[ $# -gt 0 ]]; do
    case "$1" in
        -n) DRY=1; shift ;;
        -o) LOGDIR="$2"; shift 2 ;;
        -*) echo "unknown option $1" >&2; exit 2 ;;
        *)  ONLY+=("$1"); shift ;;
    esac
done

# key:mode   mode = long | mesh | drift
JOBS=(
  "det1_long:long"        # 6-30  24 h @ 420/600
  "det1_long3:long"       # 7-7   10 h @ 440/600
  "det1_long4:long"       # 7-9   10 h @ 430/600
  "det2_long1:long"       # 7-9   10 h @ 430/600  (det2's only cosmic run)
  "det1_initial1:long"    # 7-19  initial point
  "det1_long5:long"       # 7-19  24 h efficiency @ 415/615
  "det3_initial1:long"    # 7-16  2 h  @ 420/820
  "det3_final1:long"      # 7-16  24 h @ 420/820
  "det4_initial1:long"    # 7-16  2 h  @ 430/830
  "det4_long2:long"       # 7-20  10.4 h @ 410/610
  "det1_hvscan:mesh"      # 7-2   16 pts
  "det1_hvscan2:mesh"     # 7-9    8 pts
  "det2_hvscan1:mesh"     # 7-9    8 pts
  "det1_meshscan1:mesh"   # 7-19  16 pts
  "det3_meshscan1:mesh"   # 7-16  16 pts
  "det1_driftscan2:drift" # 7-19  12 pts
  "det3_driftscan1:drift" # 7-16  11 pts
  "det4_driftscan1:drift" # 7-16  11 pts
)

mkdir -p "${LOGDIR}"
SUMMARY="${LOGDIR}/summary.tsv"
: > "${SUMMARY}"

# Refuse to start, and stop mid-batch, if the products disk gets tight.
free_gb () { df -BG --output=avail "${ANALYSIS_ROOT}" | tail -1 | tr -dc '0-9'; }
MIN_FREE_GB=3

echo "=================================================================="
echo " P2 QA re-analysis  |  MINIMAL cuts  |  $(date '+%F %T')"
echo " logs: ${LOGDIR}"
echo " free on products disk: $(free_gb) GB"
echo "=================================================================="

# Pre-flight: every stage must take its radii from the run config. A stage
# that keeps its own default silently disagrees with the rest of the chain
# (this cost us a 10-point mismatch between the scans and the long runs).
if ! python3 check_radii.py; then
    echo "!! radius guard FAILED -- fix before running, numbers would not be comparable" >&2
    exit 3
fi

python3 dump_cuts.py -o "${ANALYSIS_ROOT}/CUTS.md" 2>/dev/null && \
    echo "cuts written to ${ANALYSIS_ROOT}/CUTS.md"

n_ok=0; n_fail=0; n_skip=0
for job in "${JOBS[@]}"; do
    key="${job%%:*}"; mode="${job##*:}"

    if [[ ${#ONLY[@]} -gt 0 ]] && [[ ! " ${ONLY[*]} " =~ " ${key} " ]]; then
        continue
    fi

    args=("${key}")
    [[ "${mode}" != "long" ]] && args+=(--scan "${mode}")

    if [[ ${DRY} -eq 1 ]]; then
        echo "would run: ./run_p2_pipeline.sh ${args[*]}"
        continue
    fi

    if [[ $(free_gb) -lt ${MIN_FREE_GB} ]]; then
        echo "!! only $(free_gb) GB free -- stopping before ${key}"
        printf '%s\t%s\t%s\t%s\n' "${key}" "${mode}" "SKIPPED" "low disk" >> "${SUMMARY}"
        n_skip=$((n_skip+1))
        continue
    fi

    log="${LOGDIR}/${key}.log"
    echo ""
    echo ">>> [${key}] mode=${mode}  $(date '+%T')  -> ${log}"
    t0=$(date +%s)
    if ./run_p2_pipeline.sh "${args[@]}" > "${log}" 2>&1; then
        st=OK; n_ok=$((n_ok+1))
        # The scan modes build their own report; the long-run mode stops after
        # stage 12 and only prints the command, so invoke it here. A failed PDF
        # must not sink an otherwise good run -- record it and move on.
        if [[ "${mode}" == "long" ]]; then
            if python3 build_final_pdf.py "${key}" >> "${log}" 2>&1; then
                echo "    report PDF built"
            else
                st="OK(no-pdf)"
                echo "    !! build_final_pdf failed (stages 02-12 are fine)"
            fi
        fi
    else
        st=FAILED; n_fail=$((n_fail+1))
    fi
    dt=$(( $(date +%s) - t0 ))
    echo "    ${st} in $((dt/60))m$((dt%60))s"
    [[ "${st}" == FAILED ]] && tail -5 "${log}" | sed 's/^/      | /'
    printf '%s\t%s\t%s\t%ds\n' "${key}" "${mode}" "${st}" "${dt}" >> "${SUMMARY}"
done

echo ""
echo "=================================================================="
echo " done $(date '+%F %T')   ok=${n_ok} failed=${n_fail} skipped=${n_skip}"
echo " free on products disk: $(free_gb) GB"
echo "=================================================================="
column -t "${SUMMARY}" 2>/dev/null || cat "${SUMMARY}"
